-- Generated by gemini-3-pr
local mp = require("mp")

-- A list of standard internal mpv names for gamepad inputs.
local gamepad_keys = {
	"GAMEPAD_DPAD_UP",
	"GAMEPAD_DPAD_DOWN",
	"GAMEPAD_DPAD_LEFT",
	"GAMEPAD_DPAD_RIGHT",
	"GAMEPAD_START",
	"GAMEPAD_BACK",
	"GAMEPAD_MENU",
	"GAMEPAD_ACTION_DOWN",
	"GAMEPAD_ACTION_RIGHT",
	"GAMEPAD_ACTION_LEFT",
	"GAMEPAD_ACTION_UP",
	"GAMEPAD_LEFT_SHOULDER",
	"GAMEPAD_RIGHT_SHOULDER",
	"GAMEPAD_LEFT_TRIGGER",
	"GAMEPAD_RIGHT_TRIGGER",
	-- Analog stick movements (mpv converts axis moves to these key names)
	"GAMEPAD_LEFT_STICK_UP",
	"GAMEPAD_LEFT_STICK_DOWN",
	"GAMEPAD_LEFT_STICK_LEFT",
	"GAMEPAD_LEFT_STICK_RIGHT",
	"GAMEPAD_RIGHT_STICK_UP",
	"GAMEPAD_RIGHT_STICK_DOWN",
	"GAMEPAD_RIGHT_STICK_LEFT",
	"GAMEPAD_RIGHT_STICK_RIGHT",
}

-- 1. Create a Lua function that explicitly does nothing
local function do_nothing()
	return
end

function enable_gamepad()
	for _, key in ipairs(gamepad_keys) do
		-- Remove our blocker binding, restoring the original input.conf behavior
		mp.remove_key_binding("block-" .. key)
	end
	mp.msg.info("Window focused: Gamepad input allowed")
end

function disable_gamepad()
	for _, key in ipairs(gamepad_keys) do
		-- 2. Bind every key to the 'do_nothing' Lua function
		-- 'complex' is false because we don't need press/release details
		mp.add_forced_key_binding(key, "block-" .. key, do_nothing)
	end
	mp.msg.info("Window unfocused: Gamepad input blocked")
end

function on_focus_change(name, focused)
	if focused then
		enable_gamepad()
	else
		disable_gamepad()
	end
end

mp.observe_property("focused", "bool", on_focus_change)
